const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Cuttack, Odisha location
  const cuttackCoords = [85.9, 20.5];
  const point = ee.Geometry.Point(cuttackCoords);
  const buffer = point.buffer(50000); // 50 km buffer for stability

  // Date ranges for nighttime lights data
  const date1_start = '2019-04-01';
  const date1_end = '2019-04-30';
  const date2_start = '2019-05-01';
  const date2_end = '2019-05-31';

  // Acquire VIIRS DNB monthly data
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1');

  const col1 = collection
    .filterDate(date1_start, date1_end)
    .filterBounds(buffer);

  const col2 = collection
    .filterDate(date2_start, date2_end)
    .filterBounds(buffer);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  print(`April 2019 Images: ${size1}`);
  print(`May 2019 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    print('No data available for one or both periods.');
    print('C1');
    return;
  }

  // Select mean DNB band
  const img1 = col1.select('avg_rad').median();
  const img2 = col2.select('avg_rad').median();

  // Check pixel count validity
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  print(`April Valid Pixels: ${count1}`);
  print(`May Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    print('No valid pixels in one or both periods.');
    print('C2');
    return;
  }

  // Calculate mean brightness for each period
  const brightness1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const brightness2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  print(`April 30, 2019 Brightness: ${brightness1.toFixed(3)} nW/cm²/sr`);
  print(`May 4, 2019 Brightness: ${brightness2.toFixed(3)} nW/cm²/sr`);

  // Validate results
  if (brightness1 === null || brightness2 === null || 
      isNaN(brightness1) || isNaN(brightness2)) {
    print('Calculation resulted in invalid values.');
    print('C3');
    return;
  }

  // Check for out-of-range values (typical DNB range 0-70)
  if (brightness1 < 0 || brightness1 > 100 || brightness2 < 0 || brightness2 > 100) {
    print('Values outside expected range.');
    print('C3');
    return;
  }

  // Determine if brightness decreased
  const change = brightness2 - brightness1;
  print(`Change (May - April): ${change.toFixed(3)} nW/cm²/sr`);

  if (brightness2 < brightness1) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
